const ROOFS = [
  ["RA", [[0, 0, 35, 8], [9, 8, 26, 11]], "south"],
  ["RB", [[9, 18, 26, 21]], "north"],
  ["RC", [[9, 12, 14, 17]], "east"],
  ["RD", [[21, 12, 26, 17]], "west"],
  ["RE", [[0, 9, 8, 20]], "east"],
  ["RF", [[27, 9, 35, 20]], "west"],
  ["RG", [[0, 22, 12, 25]], "south"],
  ["RH", [[13, 22, 22, 25]], "south"],
  ["RI", [[23, 22, 35, 25]], "south"],
  ["RJ-N", [[8, 26, 27, 29]], "south"],
  ["RJ-S", [[8, 38, 27, 41]], "north"],
  ["RJ-W", [[8, 27, 11, 40]], "east"],
  ["RJ-E", [[24, 27, 27, 40]], "west"],
  ["RK-W", [[0, 28, 7, 39]], "east"],
  ["RK-E", [[28, 28, 35, 39]], "west"],
  ["RL-T", [[11, 42, 24, 46]], "north"],
  ["RL-SW", [[0, 42, 10, 46]], "north"],
  ["RL-SE", [[25, 42, 35, 46]], "north"],
];

export function build(g) {
  for (const [, rects, low] of ROOFS) band(g, rects, low);
  pediment(g, 16, 19, 0);                                   // E02: the fauces gable over the pocket (y6 x16..19, y7 x17..18)
  return g;
}
